describe('Async PDF Generation Download', () => {
  beforeEach(() => {
    cy.visit('/pdf-generator');
  });

  it('should generate and download PDF when button is clicked', () => {
    // Intercept the API call to generate PDF
    cy.intercept('POST', '/api/generate-pdf', {
      statusCode: 200,
      body: {
        url: 'https://example.com/generated-pdf.pdf',
        size: 1024,
        status: 'success'
      }
    }).as('generatePDF');

    // Verify PDF generation button is visible
    cy.get('[data-testid="generate-pdf-button"]').should('be.visible');

    // Click the button to trigger PDF generation
    cy.get('[data-testid="generate-pdf-button"]').click();

    // Wait for the API call to complete
    cy.wait('@generatePDF');

    // Verify download dialog appears
    cy.get('[data-testid="download-dialog"]').should('be.visible');

    // Verify download button is present
    cy.get('[data-testid="download-button"]').should('be.visible');

    // Click the download button
    cy.get('[data-testid="download-button"]').click();

    // Verify PDF file is downloaded
    cy.get('[data-testid="download-dialog"]').should('not.exist');
    cy.get('[data-testid="downloaded-file"]').should('be.visible');
    cy.get('[data-testid="downloaded-file"]').should('contain', 'generated-pdf.pdf');

    // Verify file size is correct
    cy.get('[data-testid="downloaded-file"]').then((file) => {
      expect(file.size).to.equal(1024);
    });

    // Verify file is not corrupted
    cy.get('[data-testid="downloaded-file"]').then((file) => {
      expect(file.type).to.equal('application/pdf');
    });
  });

  it('should handle failed PDF generation and display error message', () => {
    // Intercept the API call with a failure response
    cy.intercept('POST', '/api/generate-pdf', {
      statusCode: 500,
      body: {
        error: 'Internal server error',
        status: 'failure'
      }
    }).as('generatePDFFailure');

    // Verify PDF generation button is visible
    cy.get('[data-testid="generate-pdf-button"]').should('be.visible');

    // Click the button to trigger PDF generation
    cy.get('[data-testid="generate-pdf-button"]').click();

    // Wait for the failed API call
    cy.wait('@generatePDFFailure');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to generate PDF');

    // Verify download button is not available
    cy.get('[data-testid="download-button"]').should('not.exist');

    // Verify user is notified of the failure
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please try again later');
  });
});
